// Hook registrations: exec form (command "node" plus args), the launcher addressed through the host's
// project-directory placeholder, and the events the enforcement layer depends on. Only the critical
// PreToolUse guard fails closed; post-event and Stop hooks report without blocking.
const HOOK_SCRIPT = '.claude/hooks/claude-hook.mjs';
const HOOK_LAUNCHER = `\${CLAUDE_PROJECT_DIR}/${HOOK_SCRIPT}`;
const HOOK_EVENTS = ['pre-bash', 'post-bash', 'post-edit', 'stop'];
const REQUIRED_HOOKS = [
  { event: 'PreToolUse', tools: ['Bash', 'PowerShell'], arg: 'pre-bash' },
  { event: 'PostToolUse', tools: ['Bash', 'PowerShell'], arg: 'post-bash' },
  { event: 'PostToolUseFailure', tools: ['Bash', 'PowerShell'], arg: 'post-bash' },
  { event: 'PostToolUse', tools: ['Edit', 'MultiEdit', 'Write'], arg: 'post-edit' },
  { event: 'Stop', tools: [], arg: 'stop' },
];
const FAIL_CLOSED_EVENTS = ['PreToolUse'];

  // ---- hooks ----
  const settingsFile = path.join(root, '.claude/settings.json');
  if (!existsSync(settingsFile)) errors.push('.claude/settings.json: missing');
  else {
    let settings = null;
    try {
      settings = JSON.parse(read('.claude/settings.json'));
    } catch (error) {
      errors.push(`.claude/settings.json: invalid JSON (${error.message})`);
    }
    const scriptFile = path.join(root, HOOK_SCRIPT);
    const script = existsSync(scriptFile) ? read(HOOK_SCRIPT) : null;
    if (!script) errors.push(`${HOOK_SCRIPT}: missing`);
    for (const m of (script ?? '').matchAll(/from\s+'(\.\/[^']+)'/g)) {
      if (!existsSync(path.join(path.dirname(scriptFile), m[1]))) errors.push(`${HOOK_SCRIPT}: imported module ${m[1]} does not exist`);
    }
    const handlerMap = (script ?? '').match(/const handlers = \{([^}]*)\}/)?.[1] ?? '';
    const handled = new Set(handlerMap.split(',').map(entry => entry.split(':')[0].trim().replace(/'/g, '')).filter(Boolean));
    if (script && handled.size === 0) errors.push(`${HOOK_SCRIPT}: no 'const handlers = { … }' event map found`);
    const registered = [];
    for (const [event, groups] of Object.entries(settings?.hooks ?? {})) {
      for (const group of Array.isArray(groups) ? groups : []) {
        const tools = String(group.matcher ?? '').split('|').map(tool => tool.trim()).filter(Boolean);
        for (const hook of group.hooks ?? []) {
          const where = `.claude/settings.json ${event}${group.matcher ? ` (${group.matcher})` : ''}`;
          const args = Array.isArray(hook.args) ? hook.args : null;
          if (hook.type !== 'command') errors.push(`${where}: hook type must be 'command'`);
          if (hook.command !== 'node') {
            errors.push(`${where}: hook must use exec form — command 'node' with the script and event in args (found command '${hook.command ?? ''}')`);
          }
          if (!args || args.length !== 2 || args[0] !== HOOK_LAUNCHER) {
            errors.push(`${where}: args must be ["${HOOK_LAUNCHER}", "<event>"] so the hook starts from any working directory`);
          }
          const arg = args?.[1];
          if (!HOOK_EVENTS.includes(arg)) errors.push(`${where}: unknown hook event argument '${arg ?? ''}' (expected one of ${HOOK_EVENTS.join(', ')})`);
          else if (script && !handled.has(arg)) errors.push(`${where}: ${HOOK_SCRIPT} has no '${arg}' handler`);
          if (!(typeof hook.timeout === 'number' && hook.timeout > 0)) errors.push(`${where}: a positive timeout is required`);
          if (FAIL_CLOSED_EVENTS.includes(event)) {
            if (hook.onFailure !== 'block') errors.push(`${where}: the critical guard must fail closed (onFailure: "block")`);
          } else if (hook.onFailure !== undefined) {
            errors.push(`${where}: onFailure is reserved for the PreToolUse guard; post-event and Stop hooks must not block when they fail`);
          }
          registered.push({ event, tools, arg });
        }
      }
    }
    for (const required of REQUIRED_HOOKS) {
      const found = registered.some(entry => entry.event === required.event && entry.arg === required.arg
        && required.tools.every(tool => entry.tools.includes(tool)));
      if (!found) {
        const scope = required.tools.length > 0 ? ` for ${required.tools.join('|')}` : '';
        errors.push(`.claude/settings.json: missing ${required.event} registration${scope} running '${required.arg}'`);
      }
    }
  }
